#!/usr/bin/env node
// Builds the dashboard's browser assets into src/dashboard/generated/assets.ts.
// TypeScript is transpiled in-process (typescript.transpileModule), so this runs without esbuild and works inside
// sandboxes that cannot spawn processes. The output is deterministic: files sorted by path, no timestamps.
// usage: node scripts/build-ui.mjs [--check]   (--check exits 1 when the generated file is out of date)
import { createHash } from 'node:crypto';
import { readdir, readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import ts from 'typescript';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const CLIENT = join(ROOT, 'src', 'dashboard', 'client');
const OUT = join(ROOT, 'src', 'dashboard', 'generated', 'assets.ts');

const TYPES = {
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.html': 'text/html; charset=utf-8',
  '.svg': 'image/svg+xml',
};

async function files(dir) {
  let entries;
  try { entries = await readdir(dir, { withFileTypes: true }); }
  catch (error) { if (error.code === 'ENOENT') return []; throw error; }
  const out = [];
  for (const entry of entries) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...await files(path));
    else out.push(path);
  }
  return out;
}

/** Returns the generated module text for the client directory. */
export async function buildUiAssets(clientDir = CLIENT) {
  const assets = [];
  for (const path of (await files(clientDir)).sort()) {
    const rel = relative(clientDir, path).split(sep).join('/');
    let name = rel;
    let body;
    if (rel.endsWith('.d.ts')) continue;
    if (rel.endsWith('.ts')) {
      name = rel.replace(/\.ts$/, '.js');
      const source = await readFile(path, 'utf8');
      body = ts.transpileModule(source, {
        compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ES2022, removeComments: false },
        fileName: rel,
      }).outputText.replace(/\r\n/g, '\n').replace(/\n\/\/# sourceMappingURL=.*$/m, '');
    } else if (/\.(css|html|svg)$/.test(rel)) {
      body = (await readFile(path, 'utf8')).replace(/\r\n/g, '\n');
    } else {
      continue;
    }
    const ext = name.slice(name.lastIndexOf('.'));
    const urlPath = name === 'index.html' ? '/' : `/app/${name}`;
    const sha256 = createHash('sha256').update(body).digest('base64');
    assets.push([urlPath, { type: TYPES[ext], body, sha256 }]);
  }
  const lines = [
    '// Generated by scripts/build-ui.mjs from src/dashboard/client. Do not edit; run `npm run build:ui`.',
    '/* eslint-disable */',
    'export interface DashboardAsset { type: string; body: string; sha256: string }',
    'export const ASSETS: Record<string, DashboardAsset> = {',
    ...assets.map(([path, asset]) => `  ${JSON.stringify(path)}: ${JSON.stringify(asset)},`),
    '};',
    '',
  ];
  return lines.join('\n');
}

async function main() {
  const text = await buildUiAssets();
  if (process.argv.includes('--check')) {
    let current = '';
    try { current = await readFile(OUT, 'utf8'); } catch { /* missing counts as out of date */ }
    if (current !== text) {
      console.error('src/dashboard/generated/assets.ts is out of date. Run `npm run build:ui`.');
      process.exit(1);
    }
    console.log('Dashboard assets are up to date.');
    return;
  }
  await mkdir(dirname(OUT), { recursive: true });
  await writeFile(OUT, text);
  console.log(`Wrote ${relative(ROOT, OUT)}.`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main();
